<script setup>
import {ref,computed,onMounted} from 'vue';
import {api,photoUrl} from '../api.js';
const tab=ref('metrics'),items=ref([]),metrics=ref(null),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),note=ref(''),search=ref(''),compared=ref(new Set());
const metricRows=computed(()=>metrics.value?[
 ['Profiles',metrics.value.total_profiles],['Date enabled',metrics.value.date_enabled_profiles],['Profiles complete',metrics.value.complete_profiles],['Date profiles complete',metrics.value.complete_date_profiles],['Active in the last 7 days',metrics.value.active_7d],['Active in the last 30 days',metrics.value.active_30d],['Date likes, last 30 days',metrics.value.date_likes_30d],['Date matches created, last 30 days',metrics.value.date_matches_30d],['Active Date matches',metrics.value.active_date_matches],
]:[]);
let sequence=0;
async function load(next=tab.value){const token=++sequence;tab.value=next;loading.value=true;error.value='';try{const r=await api('/api/admin/'+tab.value+(tab.value==='members'?'?q='+encodeURIComponent(search.value):''));if(token!==sequence)return;if(tab.value==='metrics'){metrics.value=r.metrics||null;items.value=[];}else items.value=r.reports||r.requests||r.members||r.blocks||r.actions||[];}catch(e){if(token===sequence)error.value=e.message;}finally{if(token===sequence)loading.value=false;}}
async function action(section,id,values){if(busy.value)return;if(!note.value.trim()){error.value='Add a reason before taking action.';return;}busy.value=true;error.value='';notice.value='';try{const r=await api(`/api/admin/${section}/${id}`,{method:'POST',body:{...values,note:note.value.trim()}});notice.value=r.warning||'Saved.';note.value='';await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
function controls(id){search.value=id;load('members');}
onMounted(()=>load());
</script>
<template><div><div class="row heading"><h1>Admin</h1><button class="btn ghost sm" :disabled="loading" @click="load()">Refresh</button></div><nav class="chips tabs" aria-label="Admin sections"><button v-for="section in ['metrics','reports','blocks','verifications','members','actions']" :key="section" class="chip" :aria-pressed="tab===section" @click="load(section)">{{ {metrics:'Overview',reports:'Reports',blocks:'Blocks',verifications:'Verification',members:'Members',actions:'History'}[section] }}</button></nav><p v-if="error" class="err" role="alert">{{ error }}</p><p v-if="notice" class="ok" role="status">{{ notice }}</p><form v-if="tab==='members'" class="row" @submit.prevent="load()"><input v-model="search" class="grow" placeholder="Name or member ID" aria-label="Find member"><button class="btn sm">Search</button></form><label v-if="!['actions','blocks','metrics'].includes(tab)" class="field reason"><span>Action reason</span><textarea v-model="note" :disabled="busy" maxlength="1000" rows="2"></textarea></label><div v-if="loading" class="spinner"></div><section v-else-if="tab==='metrics'&&metrics" class="metrics" aria-label="PaceMate metrics"><h2>Dating activity</h2><dl><template v-for="([label,value]) in metricRows" :key="label"><dt>{{label}}</dt><dd>{{Number(value||0).toLocaleString()}}</dd></template></dl><p class="mute small">Date-enabled counts include profiles whose saved connection modes include Date, including historical mode values. Activity is based on last_active_at and may not cover older sessions. No acquisition source or landing-page conversion data is currently collected.</p></section><p v-else-if="!items.length" class="mute">{{ tab==='members'&&!search?'Search for a member.':tab==='metrics'?'Metrics are unavailable.':'Nothing here.' }}</p><div v-else class="queue"><article v-for="item in items" :key="item.id" class="card">
<template v-if="tab==='reports'"><div class="row between"><h2>{{ item.name||'Deleted member' }}</h2><span class="tag">{{ item.status }}</span></div><b>{{ item.reason }}</b><p v-if="item.details" class="details">{{ item.details }}</p><p v-if="item.resolution" class="mute small">{{ item.resolution }}</p><div class="row"><button class="btn ghost sm" @click="controls(item.reported_id)">Member controls</button><button class="btn sm" :disabled="busy" @click="action('reports',item.id,{status:'reviewed'})">Resolve</button><button class="link small" :disabled="busy" @click="action('reports',item.id,{status:'dismissed'})">Dismiss</button></div></template>
<template v-else-if="tab==='blocks'"><div class="row between"><b>{{ item.blocker_name }} → {{ item.blocked_name }}</b><time class="mute small">{{ new Date(item.created_at).toLocaleDateString() }}</time></div><button class="btn ghost sm" @click="controls(item.blocked_id)">Member controls</button></template>
<template v-else-if="tab==='verifications'"><h2>{{ item.name }}</h2><div class="comparison"><figure><img v-if="item.selfieUrl" :src="item.selfieUrl" alt="Private verification selfie"><figcaption>Selfie</figcaption></figure><figure v-for="key in item.profile_photos" :key="key"><img :src="photoUrl(key)" alt="Profile photo submitted for comparison"><figcaption>Profile</figcaption></figure></div><label class="row small"><input v-model="compared" type="checkbox" :value="item.id"> I compared the selfie with the profile photos.</label><div class="row actions"><button class="btn sm" :disabled="busy||!compared.has(item.id)" @click="action('verifications',item.id,{status:'approved',confirmed:true})">Approve</button><button class="btn danger sm" :disabled="busy" @click="action('verifications',item.id,{status:'rejected'})">Reject</button></div></template>
<template v-else-if="tab==='members'"><div class="row between"><h2>{{ item.name }}</h2><span v-if="item.suspended" class="tag">Suspended</span></div><p class="mute small">{{ item.current_city }}</p><div class="photos"><div v-for="key in item.photos" :key="key"><img :src="photoUrl(key)" alt="Member profile photo"><button class="link small" :disabled="busy" @click="action('members',item.id,{action:'remove-photo',key})">Remove photo</button></div></div><div class="row actions"><button class="btn ghost sm" :disabled="busy" @click="action('members',item.id,{action:'warn'})">Warn</button><button class="btn danger sm" :disabled="busy" @click="action('members',item.id,{action:item.suspended?'restore':'suspend'})">{{ item.suspended?'Restore account':'Suspend account' }}</button></div></template>
<template v-else><div class="row between"><b>{{ item.action }}</b><time class="mute small">{{ new Date(item.created_at).toLocaleString() }}</time></div><p class="details">{{ item.note }}</p><code>{{ item.target_id }}</code></template>
</article></div></div></template>
<style scoped>h1{font-size:30px}h2{font-size:22px}.heading,.between{justify-content:space-between}.tabs{margin:16px 0}.reason{margin-top:18px}.queue{display:grid;gap:14px}.queue .card>*+*{margin-top:12px}.metrics dl{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:0 24px;max-width:620px}.metrics dt,.metrics dd{margin:0;padding:12px 0;border-bottom:1px solid var(--line)}.metrics dd{text-align:right;font-variant-numeric:tabular-nums;font-weight:700}.metrics>p{max-width:620px;line-height:1.6;margin-top:18px}.details{white-space:pre-wrap;overflow-wrap:anywhere}.comparison{display:flex;gap:10px;overflow:auto}.comparison figure{margin:0;flex:0 0 140px}.comparison img{width:140px;height:185px;object-fit:cover;border-radius:12px}.comparison figcaption{font-size:12px;color:var(--mute);margin-top:4px}.photos{display:flex;gap:12px;overflow:auto}.photos>div{width:100px;flex:none}.photos img{height:125px;width:100px;object-fit:cover;border-radius:12px}.actions{margin-top:14px}input[type=checkbox]{width:18px;height:18px}code{font-size:12px;overflow-wrap:anywhere}</style>
